import Foundation

extension CommunicationGuides {
    static let postal = DirectoryGuide(
        cardSummary: .init(ukrainian: "Листи установ, переадресація та докази відправлення", german: "Behördenpost, Nachsendung und Versandnachweise"),
        introduction: .init(ukrainian: "Офіційні листи можуть містити короткі строки. Організуйте надійне отримання й перевіряйте пошту регулярно.", german: "Behördliche Schreiben können kurze Fristen enthalten. Sicheren Empfang organisieren und Post regelmäßig prüfen."),
        sections: [
            .init("mailbox", "envelope", "Зробіть адресу придатною для доставки", "Adresse zustellbar machen", "Вкажіть повну адресу з номером квартири; ім’я на скриньці й дзвінку має збігатися з адресатом. Після переїзду окремо повідомте нову адресу банку, страховій касі, роботодавцю та установам, де триває справа. Переадресація пошти не змінює вашу адресу в цих організаціях.", "Vollständige Adresse mit Türnummer angeben; Name an Briefkasten und Klingel muss zum Empfänger passen. Nach Umzug Bank, Krankenkasse, Arbeitgeber und Behörden mit laufenden Verfahren jeweils direkt informieren. Nachsendung ändert die dort gespeicherte Adresse nicht.", source: post),
            .init("official", "envelope.badge", "Не пропустіть офіційний лист", "Behördlichen Brief nicht verpassen", "Якщо знайшли повідомлення про вручення, одразу перевірте місце та останній день отримання. Лист RSa зазвичай вручають особисто адресату; для RSb можливе вручення уповноваженій особі за правилами доставки. Візьміть посвідчення особи, збережіть конверт і запишіть дату фактичного отримання.", "Liegt eine Hinterlegungsanzeige vor, Abholort und letzten Abholtag sofort prüfen. RSa wird grundsätzlich eigenhändig zugestellt; bei RSb ist unter Zustellregeln eine Ersatzzustellung möglich. Ausweis mitnehmen, Umschlag aufheben und tatsächlichen Empfangstag notieren.", source: postTracking),
            .init("deadline", "calendar.badge.clock", "Рахуйте строк від вручення", "Frist ab Zustellung berechnen", "Для офіційного листа юридичний строк може початися з першого дня, коли його можна забрати на пошті, навіть якщо ви відкрили лист пізніше. Наприклад, 14-денний строк оскарження може закінчитися до останнього дня зберігання. Знайдіть дату початку отримання в повідомленні та негайно перевірте строк у самому рішенні; при сумніві уточніть його в установі.", "Bei einem amtlichen Brief kann die Rechtsmittelfrist ab dem ersten Tag der Abholfrist laufen, auch wenn Sie den Brief später öffnen. Eine 14-tägige Einspruchsfrist kann daher vor dem letzten Lagertag enden. Beginn der Abholfrist auf der Verständigung ablesen und Frist im Bescheid sofort prüfen; im Zweifel bei der Behörde nachfragen.", source: deadlines),
            .init("forward", "arrowshape.turn.up.right", "Переадресуйте пошту при переїзді", "Post beim Umzug nachsenden", "Замовте Nachsendeauftrag щонайменше за три робочі дні до переїзду. Станом на жовтень 2026 року пересилання листів і дрібних відправлень у межах Австрії коштує 21,90 € за перші три календарні місяці; посилки оплачуються окремо. Перевірте актуальну ціну й строк перед оплатою. Послуга охоплює лише відправлення, передані Österreichische Post, не всі служби доставки.", "Nachsendeauftrag mindestens drei Werktage vor dem Umzug bestellen. Stand Oktober 2026 kosten Briefe und Päckchen innerhalb Österreichs 21,90 € für die ersten drei Kalendermonate; Pakete kosten extra. Aktuellen Preis und Zeitraum vor Zahlung prüfen. Der Auftrag betrifft nur Sendungen der Österreichischen Post, nicht jeden Paketdienst.", source: forwarding),
            .init("alternative", "tray", "Якщо немає надійної скриньки", "Wenn ein sicherer Briefkasten fehlt", "Уточніть у пошті умови Postlagernd або Postfach. Postlagernd зберігається обмежений час і може мати плату за відправлення; перевіряйте відділення регулярно. Така адреса не обов’язково підходить для реєстрації проживання чи офіційної доставки: перед її використанням запитайте конкретну установу, яку адресу вона приймає.", "Bei der Post Bedingungen für Postlagernd oder Postfach erfragen. Postlagernd wird nur begrenzt gelagert und kann pro Sendung kosten; Filiale regelmäßig prüfen. Diese Adresse eignet sich nicht zwangsläufig für Wohnsitzmeldung oder amtliche Zustellung: Vor Nutzung bei der zuständigen Stelle nach akzeptierter Adresse fragen.", source: postlagernd),
            .init("proof", "checkmark.seal", "Надсилайте заяви з доказом", "Anträge nachweisbar versenden", "Для важливого листа збережіть копію, чек відправлення, номер відстеження та доказ вручення, якщо обрали відповідну послугу. Перед строковою заявою перевірте вимоги конкретної установи: електронна форма, пошта чи особисте подання, а також який момент вважається своєчасним. Сам чек відправлення не завжди доводить вміст конверта.", "Bei wichtigen Schreiben Kopie, Einlieferungsbeleg, Sendungsnummer und bei passender Versandart Zustellnachweis behalten. Vor fristgebundenem Antrag Anforderungen der konkreten Stelle prüfen: Onlineformular, Post oder persönliche Abgabe und welcher Zeitpunkt fristwahrend ist. Ein Einlieferungsbeleg allein beweist nicht immer den Inhalt des Kuverts.", source: post)
        ], sources: [post, postTracking, deadlines, forwarding, postlagernd]
    )
